import assert from 'node:assert/strict';
import cp from 'node:child_process';
import threads from 'node:worker_threads';
import { syncBuiltinESMExports } from 'node:module';
import { createHash, randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createNativePlatform } from '../dist/platform.js';
import { ApprovedGit, discover } from '../dist/core/git.js';
import { loadPolicy } from '../dist/core/policy.js';

// Parent runs this only after building the approved worker source. No fixture/source writes.
const root = 'C:/Users/tno/Documents/GitHub/Agent-Native-Git';
const fixture = 'C:/Users/tno/AppData/Local/Temp/angit stage1 BPqzUG';
const policyPath = join(fixture, 'owner private', 'approved policy.json');
const declaration = JSON.parse(readFileSync(policyPath, 'utf8'));
const privateRoot = join(fixture, 'owner private', 'state', 'projects', 'prj_b9c7e84cc550284fb2133cc3ec9b088397ed1216aa949515');
const platform = createNativePlatform(root);
const repository = discover(platform, declaration.repoRoot);
loadPolicy(platform, repository, policyPath, root);
assert.equal(createHash('sha256').update(readFileSync(declaration.git.executable.path)).digest('hex'), declaration.git.executable.sha256);
const git = new ApprovedGit(platform, repository, declaration.git, privateRoot);
const format = (await git.run(['rev-parse', '--show-object-format'])).trim();
assert.ok(format === 'sha1' || format === 'sha256');
const content = Buffer.from('approved read-only Git deadline pipe input\n');
const expectedOutput = Buffer.from(`${createHash(format).update(`blob ${content.length}\0`).update(content).digest('hex')}\n`);
const powershell = join(process.env.SystemRoot, 'System32', 'WindowsPowerShell', 'v1.0', 'powershell.exe');
const originalWorker = threads.Worker;
const sleeper = new Int32Array(new SharedArrayBuffer(4));
const records = [];
let active;
threads.Worker = class extends originalWorker {
  constructor(url, options) {
    super(url, options);
    if (!active || options.workerData?.args?.at(-1) !== active.pipePath) return;
    const record = active;
    record.workerCreatedAtMs = Date.now();
    record.arguments = options.workerData.args;
    this.once('online', () => {
      record.workerOnlineAtMs = Date.now();
      record.blockBeginAtMs = Date.now();
      if (record.blockMs) Atomics.wait(sleeper, 0, 0, record.blockMs);
      record.blockEndAtMs = Date.now();
    });
    this.once('message', value => {
      record.workerMessageAtMs = Date.now();
      record.workerResult = { status: value.status, signal: value.signal, errorCode: value.errorCode, stdoutBytes: value.stdout.byteLength, stderrBytes: value.stderr.byteLength };
    });
    this.once('exit', code => { record.workerExitAtMs = Date.now(); record.workerExitCode = code; });
  }
};
