function observePipe(record) {
  // A finite owner-only named pipe supplies genuinely delayed bytes to real Git. No -w,
  // provider, network, retained service, or changes to the preserved checkout/state.
  const encodedContent = content.toString('base64');
  const script = [
    `$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';`,
    `$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User;$acl=[IO.Pipes.PipeSecurity]::new();`,
    `$acl.SetOwner($sid);$acl.SetAccessRuleProtection($true,$false);`,
    `$acl.AddAccessRule([IO.Pipes.PipeAccessRule]::new($sid,[IO.Pipes.PipeAccessRights]::FullControl,[Security.AccessControl.AccessControlType]::Allow));`,
    `$pipe=[IO.Pipes.NamedPipeServerStream]::new('${record.pipeName}',[IO.Pipes.PipeDirection]::Out,1,[IO.Pipes.PipeTransmissionMode]::Byte,[IO.Pipes.PipeOptions]::Asynchronous,4096,4096,$acl);$p=$null;`,
    `try{$connection=$pipe.BeginWaitForConnection($null,$null);[Console]::WriteLine('READY');$clock=[Diagnostics.Stopwatch]::StartNew();`,
    `while($null -eq $p){if($clock.ElapsedMilliseconds -ge 20000){throw 'Owned Git did not open the finite input fixture'};`,
    `$candidate=Get-CimInstance Win32_Process -Filter 'ParentProcessId = ${process.pid} AND Name = "git.exe"'|Where-Object {$_.ExecutablePath -ieq '${declaration.git.executable.path.replaceAll("'", "''")}' -and $_.CommandLine -and $_.CommandLine.Contains('${record.pipeName}')}|Select-Object -First 1;`,
    `if($candidate){$p=[Diagnostics.Process]::GetProcessById($candidate.ProcessId);$handle=$p.Handle;$start=$p.StartTime.ToUniversalTime()}else{[Threading.Thread]::Sleep(20)}};`,
    `if(-not $connection.AsyncWaitHandle.WaitOne(5000)){throw 'Owned Git did not connect to its input fixture'};$pipe.EndWaitForConnection($connection);`,
    `$connected=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();[Threading.Thread]::Sleep(${record.inputDelayMs});$write='delivered';`,
    `try{$bytes=[Convert]::FromBase64String('${encodedContent}');$pipe.Write($bytes,0,$bytes.Length);$pipe.Flush()}catch [IO.IOException]{$write='reader_closed'};$pipe.Dispose();`,
    `if(-not $p.WaitForExit(5000)){throw 'Owned Git native exit was not observed'};$end=$p.ExitTime.ToUniversalTime();`,
    `[Console]::WriteLine((@{pid=$p.Id;exitCode=$p.ExitCode;startAtMs=[DateTimeOffset]::new($start).ToUnixTimeMilliseconds();exitAtMs=[DateTimeOffset]::new($end).ToUnixTimeMilliseconds();nativeElapsedMs=($end-$start).TotalMilliseconds;connectedAtMs=$connected;inputWrite=$write}|ConvertTo-Json -Compress))`,
    `}finally{$pipe.Dispose();if($null -ne $p){$p.Dispose()}}`,
  ].join('');
  const observer = cp.spawn(powershell, ['-NoLogo', '-NoProfile', '-NonInteractive', '-EncodedCommand', Buffer.from(script, 'utf16le').toString('base64')], { shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });
