  const ready = new Promise((resolve, reject) => { resolveReady = resolve; rejectReady = reject; });
  ready.catch(() => {});
  const timer = setTimeout(() => observer.kill(), 45000);
  const done = new Promise((resolve, reject) => {
    observer.once('error', error => { clearTimeout(timer); rejectReady(error); reject(error); });
    observer.once('close', code => {
      clearTimeout(timer);
      if (code !== 0 || stderr) { const error = new Error(`Native observer failed: ${code}: ${stderr}`); rejectReady(error); reject(error); }
      else { try { record.native = JSON.parse(stdout.trim().split(/\r?\n/u).at(-1)); resolve(); } catch (error) { rejectReady(error); reject(error); } }
    });
  });
  done.catch(() => {});
  observer.stdout.on('data', bytes => { stdout += bytes; if (stdout.includes('READY\n') || stdout.includes('READY\r\n')) resolveReady(); });
  observer.stderr.on('data', bytes => { stderr += bytes; });
  return { ready, done };
}

try {
  for (const [kind, inputDelayMs, blockMs] of [['baseline', 300, 0], ['early-exit-blocked', 300, 17000], ['slow-input-blocked', 18000, 17000]]) {
    const pipeName = `angit-git-deadline-${randomBytes(16).toString('hex')}`;
    active = { kind, inputDelayMs, blockMs, pipeName, pipePath: `\\\\.\\pipe\\${pipeName}` };
    const observer = observePipe(active);
    await observer.ready;
    try {
      const bytes = await git.runBytes(['hash-object', '--no-filters', '--', active.pipePath]);
      active.result = { status: 'success', bytes: bytes.length, sha256: createHash('sha256').update(bytes).digest('hex') };
      if (kind !== 'slow-input-blocked') assert.deepEqual(bytes, expectedOutput);
    } catch (error) {
      active.result = { status: 'error', code: error.code, message: error.message };
    }
    active.promiseAtMs = Date.now();
    await observer.done;
    records.push(active);
    assert.equal(active.workerExitCode, 0);
    assert.ok(active.promiseAtMs >= active.workerExitAtMs, 'consumer settled before finite worker exit');
    if (kind === 'slow-input-blocked') {
      assert.equal(active.result.code, 'GIT_TIMEOUT');
      assert.equal(active.workerResult.errorCode, 'ETIMEDOUT');
      assert.ok(active.native.nativeElapsedMs >= 14500 && active.native.nativeElapsedMs < 16500, 'actual Git was not terminated at its unchanged native 15s deadline');
      assert.ok(active.native.exitAtMs < active.blockEndAtMs, 'Git survived until the main-thread block ended');
    } else {
      assert.equal(active.result.status, 'success');
      assert.equal(active.native.exitCode, 0);
      assert.equal(active.workerResult.errorCode, null);
      assert.ok(active.native.nativeElapsedMs < 15000);
      if (blockMs) assert.ok(active.native.exitAtMs < active.blockEndAtMs && active.workerMessageAtMs - active.native.exitAtMs > 10000, 'early native exit did not precede delayed main-thread delivery');
    }
  }
  active = undefined;
  const missingRef = `refs/angit/smoke_${randomBytes(16).toString('hex')}`;
  assert.equal(await git.ref(missingRef), null, 'absent-exit behavior changed');
  let nonzero;
  try { await git.runBytes(['cat-file', '-t', '0000000000000000000000000000000000000000']); } catch (error) { nonzero = error; }
  assert.equal(nonzero?.code, 'GIT_EXECUTION_FAILED');
  assert.ok(Buffer.isBuffer(nonzero.cause.stderr));
  assert.ok(!nonzero.message.includes(nonzero.cause.stderr.toString('utf8')), 'raw stderr leaked publicly');
  console.log(JSON.stringify({ schemaVersion: 'angit-git-deadline-smoke/v1', stage: 'after', node: process.version, fixtureReadOnly: true, approvedExecutableHash: declaration.git.executable.sha256, deadlineMs: 15000, records, absentRef: true, nonzeroInternalStderr: true }, null, 2));
} catch (error) {
  console.log(JSON.stringify({ stage: 'after', records, active, failure: { code: error.code, message: error.message } }, null, 2));
  throw error;
} finally { threads.Worker = originalWorker; syncBuiltinESMExports(); }
